/**
 * GitHub API and Git Commit types.
 */
export interface IGitHubConfig {
  accessToken: string;
  username: string;
  repository: string; // e.g. "LeetCode-Solutions"
  branch: string; // default "main"
  syncWorkflow?: 'direct' | 'pr_issue'; // 'direct' = direct commit to main, 'pr_issue' = Issue -> Branch -> Commit -> PR
}

export interface ICommitAuthor {
  name: string;
  email: string;
  date: string; // ISO 8601 string, e.g. "2023-05-15T14:32:00Z"
}

export interface ICommitFile {
  path: string; // Relative file path in repository (e.g. "leetcode/0001-two-sum/README.md")
  content: string; // File content
}

export interface ICommitResult {
  success: boolean;
  commitSha?: string;
  commitUrl?: string;
  error?: string;
}

export interface IBatchCommitItem {
  files: ICommitFile[];
  message: string;
  authorTimestamp?: string;
  metadata?: {
    platform: string;
    titleSlug: string;
    problemId: string;
    title: string;
    difficulty: string;
    topics: string[];
  };
}

export interface IBatchCommitResult {
  success: boolean;
  totalItems: number;
  committedCount: number;
  finalCommitSha?: string;
  error?: string;
}
